/**
 * Per-tag Navaar Tags icons, transcribed from the user-supplied 96-shape icon
 * pack (shape-icon-pack-96-icons.zip). Each glyph is one hand-picked shape
 * from that pack, kept exactly as the pack drew it — no redrawing, only a
 * choice of which of the 96 best fits each tag. Mirrors the icon() factory in
 * ../../icons.tsx, but these are smooth vector marks on a 256x256 canvas
 * rather than the app's 24x24 pixel-grid icon set, so there's no crispEdges.
 */
import type { SVGProps } from "react";

export interface ShapeIconProps extends Omit<SVGProps<SVGSVGElement>, "children"> {
  size?: number;
}

function shapeIcon(children: React.ReactNode) {
  return function Glyph({ size = 20, ...props }: ShapeIconProps) {
    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 256 256"
        fill="currentColor"
        aria-hidden="true"
        focusable="false"
        {...props}
      >
        {children}
      </svg>
    );
  };
}

